#include <iostream>
#include <vector>
#include <numeric>
using namespace std;

struct DSU {
    vector<int> parent, sizeOf;
    DSU(int n) : parent(n + 1), sizeOf(n + 1, 1) {
        iota(parent.begin(), parent.end(), 0);
    }
    int find(int v) {
        return parent[v] == v ? v : parent[v] = find(parent[v]);
    }
    bool unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) return false;
        if (sizeOf[a] < sizeOf[b]) swap(a, b);
        parent[b] = a;
        sizeOf[a] += sizeOf[b];
        return true;
    }
};

int main() {
    DSU dsu(3);
    dsu.unite(1, 2);
    dsu.unite(2, 3);
    cout << (dsu.find(1) == dsu.find(3)) << '\n';
    return 0;
}
